package dev.interview.orders.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**","/actuator/prometheus").permitAll().requestMatchers("/api/**").hasAnyRole("CUSTOMER","SUPPORT").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(jwtConverter()))).build();}
 @Bean JwtAuthenticationConverter jwtConverter(){var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(jwt->{Map<String,Object> access=jwt.getClaim("realm_access");if(access==null)return List.of();Object raw=access.get("roles");if(!(raw instanceof Collection<?> roles))return List.of();return roles.stream().map(Object::toString).map(r->(GrantedAuthority)new SimpleGrantedAuthority("ROLE_"+r)).toList();});return c;}
}
